import { liveCheckoutHostClaims, recordCheckoutHostClaim, withCheckoutHostLock, } from "./checkout-host-claims.js";
import { CHECKOUT_NAME_ENV, canonicalCheckoutPath, getCheckoutName, sanitizeCheckoutName, setCheckoutHostSuffix, } from "./checkout-id.js";
import { CHECKOUT_HOST_SUFFIX_ENV, getCheckoutDomain } from "./constants.js";
/**
 * Whether another running stack derives the same checkout name. Names come from the
 * checkout folder (or `FLISK_CHECKOUT_NAME` for the current one), matching #4694 and
 * the host names generated by `getCheckoutDomain` (#4697).
 */
export function checkoutNameCollides(projectRoot, otherRoots, env = process.env) {
    const ownName = sanitizeCheckoutName(env[CHECKOUT_NAME_ENV] ?? getCheckoutName(projectRoot));
    const ownPath = canonicalCheckoutPath(projectRoot);
    return otherRoots.some((root) => {
        if (canonicalCheckoutPath(root) === ownPath)
            return false;
        return sanitizeCheckoutName(getCheckoutName(root)) === ownName;
    });
}
/**
 * Resolve a host collision before Tilt starts: append `-<first 4 id chars>` to the
 * checkout host and persist it in the local checkout record so later commands print
 * the same host. An explicit `FLISK_CHECKOUT_HOST_SUFFIX` always wins.
 */
export function applyCheckoutHostCollisionSuffix(projectRoot, identity, otherRoots, env = process.env, options = {}) {
    if (!getCheckoutDomain(projectRoot, env))
        return null;
    const explicit = env[CHECKOUT_HOST_SUFFIX_ENV];
    if (explicit !== undefined)
        return explicit || null;
    if (!checkoutNameCollides(projectRoot, otherRoots, env))
        return null;
    const suffix = `-${identity.id.slice(0, 4)}`;
    env[CHECKOUT_HOST_SUFFIX_ENV] = suffix;
    // The caller persists the suffix once it knows this run will start or replace Tilt: a run that only
    // attaches to, or refuses against, a running stack must leave that stack's recorded host alone.
    if (options.persist !== false)
        setCheckoutHostSuffix(projectRoot, suffix);
    return suffix;
}
/**
 * `applyCheckoutHostCollisionSuffix` for a real `flisk up`: the collision check and this checkout's claim
 * on its host run as one step under a lock shared by every checkout, so two starts in two worktrees at the
 * same time cannot both see no other stack and both keep the unsuffixed host. Live claims of other `flisk up`
 * runs count as running stacks next to the Tilt instances in `runningRoots`. The suffix is applied to `env`
 * but not persisted: persist it with `setCheckoutHostSuffix` once the run starts Tilt.
 */
export async function claimCheckoutHost(projectRoot, identity, runningRoots, env = process.env, options = {}) {
    if (!getCheckoutDomain(projectRoot, env))
        return null;
    return withCheckoutHostLock(() => {
        const otherRoots = [...runningRoots, ...liveCheckoutHostClaims(projectRoot, options)];
        const suffix = applyCheckoutHostCollisionSuffix(projectRoot, identity, otherRoots, env, {
            persist: false,
        });
        recordCheckoutHostClaim(projectRoot, options);
        return suffix;
    }, options.home);
}
